import copy,re

def plan_gc(snapshot,project,now):
    if not isinstance(project,str) or not re.fullmatch(r"[a-z][a-z0-9_-]{0,39}",project) or type(now) is not int or now<0:
        raise ValueError("explicit project/time required")
    if not isinstance(snapshot,dict) or snapshot.get("complete") is not True:
        raise ValueError("complete all-container inventory required")
    if set(snapshot)!={"complete","containers","volumes","images"} or any(not isinstance(snapshot[k],list) for k in ("containers","volumes","images")):
        raise ValueError("invalid inventory")
    def index(rows,key):
        result={}
        for row in rows:
            if not isinstance(row,dict) or not isinstance(row.get(key),str) or not row[key] or row[key] in result:
                raise ValueError("duplicate/invalid identity")
            if not isinstance(row.get("labels"),dict) or any(not isinstance(k,str) or not isinstance(v,str) for k,v in row["labels"].items()):
                raise ValueError("invalid labels")
            result[row[key]]=row
        return result
    containers=index(snapshot["containers"],"id");volumes=index(snapshot["volumes"],"name");images=index(snapshot["images"],"id")
    referenced=set()
    for row in containers.values():
        if row.get("state") not in {"running","paused","restarting","created","exited","dead","removing"} or not isinstance(row.get("volumes"),list):
            raise ValueError("unknown container lifecycle")
        if row.get("image") not in images or any(not isinstance(v,str) or v not in volumes for v in row["volumes"]):
            raise ValueError("incomplete referenced objects")
        referenced.update(row["volumes"])
    def gate(labels):
        if labels.get("opsforge.project")!=project:return "other_or_unmanaged_project"
        if labels.get("opsforge.gc.keep")=="true":return "explicit_retention"
        if labels.get("opsforge.gc.approved")!="true":return "not_approved"
        not_before=labels.get("opsforge.gc.not_before","")
        if not re.fullmatch(r"0|[1-9][0-9]{0,18}",not_before):return "invalid_retention_time"
        if int(not_before)>now:return "retention_window"
        return None
    rows=[]
    for identity,row in containers.items():
        reason=gate(row["labels"])
        if reason is None and row["state"] not in {"created","exited","dead"}:reason="active_or_transitioning"
        rows.append(dict(kind="container",id=identity,candidate=reason is None,reason=reason or "approved_stopped"))
    for identity,row in volumes.items():
        reason=gate(row["labels"])
        if identity in referenced:reason="referenced_by_existing_container"
        rows.append(dict(kind="volume",id=identity,candidate=reason is None,reason=reason or "approved_unreferenced"))
    # This review contract never authorizes image removal: rollback/external references need separate evidence.
    for identity,row in images.items():
        rows.append(dict(kind="image",id=identity,candidate=False,reason="image_scope_not_approved"))
    return {"project":project,"evaluated_at":now,"rows":sorted(rows,key=lambda r:(r["kind"],r["id"])),
        "execution_authorized":False,"reinventory_after_container_removal":True}
